manage_schedule.handler:
.handleInvocation(async ctx => {
    let client = new SensiboClient(ctx.auth.token);
    let { deviceId, action } = ctx.input;

    if (action === 'list') {
      let schedules = await client.listSchedules(deviceId);
      let mapped = (schedules || []).map((s: any) => ({
        scheduleId: s.id,
        isEnabled: s.isEnabled,
        recurOnDaysOfWeek: s.recurOnDaysOfWeek,
        timeOfDay: s.timeOfDay,
        acState: s.acState
          ? {
              on: s.acState.on,
              mode: s.acState.mode,
              targetTemperature: s.acState.targetTemperature,
              temperatureUnit: s.acState.temperatureUnit,
              fanLevel: s.acState.fanLevel,
              swing: s.acState.swing
            }
          : undefined
      }));

      return {
        output: { deviceId, schedules: mapped },
        message: `Found **${mapped.length}** schedule(s) for device **${deviceId}**.`
      };
    }

    if (action === 'delete') {
      await client.deleteSchedule(deviceId, ctx.input.scheduleId!);
      return {
        output: { deviceId, deleted: true },
        message: `Deleted schedule **${ctx.input.scheduleId}** from device **${deviceId}**.`
      };
    }

    if (action === 'create') {
      let scheduleData: Record<string, any> = {
        isEnabled: ctx.input.isEnabled ?? true,
        recurOnDaysOfWeek: ctx.input.recurOnDaysOfWeek,
        timeOfDay: ctx.input.timeOfDay,
        acState: ctx.input.acState
      };
      let result = await client.createSchedule(deviceId, scheduleData);
      return {
        output: {
          deviceId,
          schedule: {
            scheduleId: result.id,
            isEnabled: result.isEnabled,
            recurOnDaysOfWeek: result.recurOnDaysOfWeek,
            timeOfDay: result.timeOfDay,
            acState: result.acState
          }
        },
        message: `Created schedule **${result.id}** on device **${deviceId}** for ${ctx.input.recurOnDaysOfWeek?.join(', ')} at ${ctx.input.timeOfDay}.`
      };
    }

    // action === 'update'
    let updateData: Record<string, any> = {};
    if (ctx.input.isEnabled !== undefined) updateData.isEnabled = ctx.input.isEnabled;
    if (ctx.input.recurOnDaysOfWeek)
      updateData.recurOnDaysOfWeek = ctx.input.recurOnDaysOfWeek;
    if (ctx.input.timeOfDay) updateData.timeOfDay = ctx.input.timeOfDay;
    if (ctx.input.acState) updateData.acState = ctx.input.acState;

    let result = await client.updateSchedule(deviceId, ctx.input.scheduleId!, updateData);
    return {
      output: {
        deviceId,
        schedule: {
          scheduleId: result.id || ctx.input.scheduleId!,
          isEnabled: result.isEnabled,
          recurOnDaysOfWeek: result.recurOnDaysOfWeek,
          timeOfDay: result.timeOfDay,
          acState: result.acState
        }
      },
      message: `Updated schedule **${ctx.input.scheduleId}** on device **${deviceId}**.`
    };
  })

get_door_sensor_events.handler:
.handleInvocation(async ctx => {
    let client = new SensiboClient(ctx.auth.token);
    let days = ctx.input.days ?? 1;

    let rawEvents = await client.getDoorSensorEvents(ctx.input.deviceId, days);

    let events = (rawEvents || []).map((e: any) => ({
      eventId: e.id,
      state: e.state,
      timestamp: e.time?.time || e.timestamp
    }));

    return {
      output: {
        deviceId: ctx.input.deviceId,
        events
      },
      message: `Retrieved **${events.length}** door/window sensor event(s) from device **${ctx.input.deviceId}** over the last ${days} day(s).`
    };
  })

methods.listSchedules:
async listSchedules(deviceId: string): Promise<any[]> {
  let response = await this.http.get(`/pods/${deviceId}/schedules`);
  return response.data.result;
}

methods.createSchedule:
async createSchedule(deviceId: string, schedule: Record<string, any>): Promise<any> {
  let response = await this.http.post(`/pods/${deviceId}/schedules`, schedule);
  return response.data.result;
}

methods.getSchedule:
async getSchedule(deviceId: string, scheduleId: string): Promise<any> {
  let response = await this.http.get(`/pods/${deviceId}/schedules/${scheduleId}`);
  return response.data.result;
}

methods.updateSchedule:
async updateSchedule(
  deviceId: string,
  scheduleId: string,
  schedule: Record<string, any>
): Promise<any> {
  let response = await this.http.put(`/pods/${deviceId}/schedules/${scheduleId}`, schedule);
  return response.data.result;
}

methods.deleteSchedule:
async deleteSchedule(deviceId: string, scheduleId: string): Promise<void> {
  await this.http.delete(`/pods/${deviceId}/schedules/${scheduleId}`);
}

methods.getDoorSensorEvents:
async getDoorSensorEvents(deviceId: string, days: number = 1): Promise<any[]> {
  let response = await this.http.get(`/pods/${deviceId}/doorSensors/events`, {
    params: { days }
  });
  return response.data.result;
}
